import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import axios from 'axios';

function LeavePage() {
  const [leaveRequest, setLeaveRequest] = useState({
    name: '',
    reason: '',
    startDate: '',
    endDate: ''
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setLeaveRequest({
      ...leaveRequest,
      [name]: value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const response = await axios.post('https://jsonplaceholder.typicode.com/posts', leaveRequest);
      console.log('Leave Request Submitted:', response.data);
    } catch (error) {
      console.error('Error submitting leave request:', error);
    }
  };

  return (
    <div>
      <h1>Submit a Leave Request</h1>
      <form onSubmit={handleSubmit}>
        <div>
          <label>Name:</label>
          <input type="text" name="name" value={leaveRequest.name} onChange={handleChange} required />
        </div>
        <div>
          <label>Reason:</label>
          <input type="text" name="reason" value={leaveRequest.reason} onChange={handleChange} required />
        </div>
        <div>
          <label>Start Date:</label>
          <input type="date" name="startDate" value={leaveRequest.startDate} onChange={handleChange} required />
        </div>
        <div>
          <label>End Date:</label>
          <input type="date" name="endDate" value={leaveRequest.endDate} onChange={handleChange} required />
        </div>
        <button type="submit">Submit</button>
      </form>
      <Link to="/">Go to Home Page</Link>
    </div>
  );
}

export default LeavePage;